/**
 * The simple team (model team@1): the heading, a description and the members as a list, each with a portrait,
 * the name and a line. Axes: cols (2, 3, 4 columns from md up), surface (plain, cards).
 */
import { type ReactNode } from "react";
import { Block, Card, Container, List, ListItem, Stack, Text, Title } from "../compose";
import { MediaFrame } from "../components/media-frame";
import { cn } from "../utils";
import type { SimpleMember } from "./team-simple.types";

export type TeamSimpleProps = {
  id: string;
  title: string;
  description?: string;
  members: SimpleMember[];
  level?: 1 | 2 | 3;
  padding?: "compact" | "standard" | "spacious";
  cols?: "2" | "3" | "4";
  surface?: "plain" | "cards";
  landmarkLabel?: string;
};

export function TeamSimple({
  id,
  title,
  description = "",
  members,
  level = 2,
  padding = "standard",
  cols = "3",
  surface = "plain",
  landmarkLabel,
}: TeamSimpleProps) {
  const titleId = id + "-title";
  return (
    <Block
      tag="section"
      className={
        (padding as string) === "compact" ? "py-8 lg:py-16"
        : (padding as string) === "spacious" ? "py-24 lg:py-40"
        : "py-16 lg:py-32"
      }
      aria-labelledby={(landmarkLabel ? undefined : titleId)}
      aria-label={landmarkLabel}
      data-slot="team-simple"
    >
      <Container className="mx-auto w-full max-w-6xl px-4">
        <Stack gap="12" align="stretch">
          <Stack gap="4" className="max-w-2xl">
            <Title as={level} size="3xl" weight="bold" className="tracking-tight" id={titleId}>
              {title}
            </Title>
            {description ? (
              <Text size="base" className="text-muted-foreground">
                {description}
              </Text>
            ) : null}
          </Stack>
          <List
            tag="ul"
            className={cn(
              "m-0 grid w-full list-none grid-cols-1 gap-8 p-0 sm:grid-cols-2",
              (
                (cols as string) === "2" ? ""
                : (cols as string) === "3" ? "md:grid-cols-3"
                : "md:grid-cols-4"
              )
            )}
          >
            {(members ?? []).map((m) => (
              <ListItem key={m.id} className={(((surface as string) === "cards") ? "flex" : "flex flex-col gap-4")} data-slot="member">
                {((surface as string) === "cards") ? (
                  <Card className="flex w-full flex-col gap-4 p-6">
                    <MediaFrame alt={m.title} src={m.avatar} ratio="1/1" className="size-16 rounded-full" />
                    <Stack gap="2">
                      <Title as={(level + 1)} size="lg" weight="semibold">
                        {m.title}
                      </Title>
                      {m.description ? (
                        <Text size="sm" className="text-muted-foreground">
                          {m.description}
                        </Text>
                      ) : null}
                    </Stack>
                  </Card>
                ) : (
                  <>
                    <MediaFrame alt={m.title} src={m.avatar} ratio="1/1" className="size-16 rounded-full" />
                    <Stack gap="2">
                      <Title as={(level + 1)} size="lg" weight="semibold">
                        {m.title}
                      </Title>
                      {m.description ? (
                        <Text size="sm" className="text-muted-foreground">
                          {m.description}
                        </Text>
                      ) : null}
                    </Stack>
                  </>
                )}
              </ListItem>
            ))}
          </List>
        </Stack>
      </Container>
    </Block>
  );
}

